import React from 'react';

/** Props for the {@link Markdown} component. */
export interface MarkdownProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Additional CSS class names. */
  className?: string;
  /** Pre-rendered HTML or React nodes to display with markdown styling. */
  children?: React.ReactNode;
}

/**
 * Markdown renderer container for AI chat content.
 * Applies `sk-markdown` typography styles to child content.
 * This component does not parse raw markdown; pass pre-rendered HTML or React elements.
 */
export const Markdown = React.forwardRef<HTMLDivElement, MarkdownProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-markdown${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

Markdown.displayName = 'Markdown';

/**
 * skeehn — Markdown Component
 *
 * @component sk-markdown
 * @elements  h1-h6 | p | a | code | pre | ul/ol | li | blockquote | hr | table | img
 * @states    [data-loading] | [data-skeleton]
 * @features  Styled prose for AI output, list markers, code blocks with dither, tables
 * @a11y      Semantic HTML elements, link underlines, sufficient contrast
 * @print     Full content visible, links show URLs
 */

.sk-markdown {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-sm);
  line-height: var(--sk-line-height);
  color: hsl(var(--sk-foreground));
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.sk-markdown > *:first-child { margin-top: 0; }
.sk-markdown > *:last-child { margin-bottom: 0; }

.sk-markdown h1, .sk-markdown h2, .sk-markdown h3,
.sk-markdown h4, .sk-markdown h5, .sk-markdown h6 {
  margin: var(--sk-space-4) 0 var(--sk-space-2);
  font-family: var(--sk-font-mono);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.3;
}

.sk-markdown h1 { font-size: var(--sk-font-size-xl); text-transform: uppercase; }
.sk-markdown h2 { font-size: var(--sk-font-size-lg); text-transform: uppercase; }
.sk-markdown h3 { font-size: var(--sk-font-size-base); }
.sk-markdown h4 { font-size: var(--sk-font-size-sm); }

.sk-markdown p {
  margin: var(--sk-space-2) 0;
}

.sk-markdown strong { font-weight: 700; }
.sk-markdown em { font-style: italic; }

.sk-markdown a {
  color: hsl(var(--sk-primary));
  text-decoration: underline;
  text-underline-offset: 2px;
}

.sk-markdown a:hover {
  opacity: 0.8;
}

.sk-markdown code:not(pre code) {
  font-family: var(--sk-font-mono);
  font-size: 0.85em;
  padding: 0.1em 0.35em;
  background: hsl(var(--sk-muted));
  border: var(--sk-border);
  border-radius: var(--sk-radius);
}

.sk-markdown pre {
  margin: var(--sk-space-3) 0;
  padding: var(--sk-space-3);
  background: hsl(var(--sk-muted) / 0.3);
  border: var(--sk-border);
  border-radius: var(--sk-radius);
  overflow-x: auto;
  position: relative;
}

.sk-markdown pre::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  opacity: calc(var(--sk-dither-opacity, 0.15) * 0.08);
  pointer-events: none;
  border-radius: inherit;
}

.sk-markdown pre code {
  font-size: var(--sk-font-size-xs);
  line-height: 1.6;
  background: none;
  border: none;
  padding: 0;
  position: relative;
  z-index: 1;
}

.sk-markdown ul, .sk-markdown ol {
  margin: var(--sk-space-2) 0;
  padding-left: var(--sk-space-6);
}

.sk-markdown li {
  margin: var(--sk-space-1) 0;
}

.sk-markdown ul li::marker { content: "▸ "; color: hsl(var(--sk-muted-foreground)); }
.sk-markdown ol li::marker { color: hsl(var(--sk-muted-foreground)); }

.sk-markdown blockquote {
  margin: var(--sk-space-3) 0;
  padding: var(--sk-space-2) var(--sk-space-4);
  border-left: 3px solid hsl(var(--sk-border-color));
  color: hsl(var(--sk-muted-foreground));
  font-style: italic;
}

.sk-markdown hr {
  margin: var(--sk-space-4) 0;
  border: none;
  border-top: 1px solid hsl(var(--sk-border-color));
}

.sk-markdown table {
  width: 100%;
  margin: var(--sk-space-3) 0;
  border-collapse: collapse;
}

.sk-markdown th, .sk-markdown td {
  padding: var(--sk-space-2) var(--sk-space-3);
  text-align: left;
  border-bottom: var(--sk-border);
  font-size: var(--sk-font-size-xs);
}

.sk-markdown th {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.sk-markdown img {
  max-width: 100%;
  border-radius: var(--sk-radius);
  border: var(--sk-border);
}

/* Loading */
.sk-markdown[data-loading] { position: relative; opacity: 0.6; }
.sk-markdown[data-loading]::after {
  content: ""; position: absolute; inset: 0;
  background-image: var(--sk-dither-pattern); background-repeat: repeat;
  opacity: 0.05; animation: sk-pulse-dither 1.5s ease-in-out infinite; pointer-events: none;
}

/* Skeleton */
.sk-markdown[data-skeleton] > * {
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius);
  min-height: 1rem;
  margin: var(--sk-space-2) 0;
}

@media print {
  .sk-markdown pre::before { display: none; }
  .sk-markdown a::after { content: " (" attr(href) ")"; font-size: 0.7em; color: hsl(var(--sk-muted-foreground)); }
  .sk-markdown[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-markdown[data-loading]::after { animation: none; }
  .sk-markdown[data-skeleton] > * { animation: none; background: hsl(var(--sk-muted)); }
}
